/** Structure key for Three.js mesh reuse (excludes fold angle â€” joints move, topology does not). */
let threeRendererMeshStructureKey = null;
let threeRendererMeshCounts = null;

function computeMeshStructureKey() {
    const sp = state.solarPanels;
    const params = [
        state.modules,
        state.hLengthFt,
        state.vLengthFt,
        state.pivotPct,
        state.hobermanAng,
        state.pivotAng,
        state.hStackCount,
        state.vStackCount,
        state.vStackReverse,
        state.offsetTopIn,
        state.offsetBotIn,
        state.vertEndOffset,
        state.bracketHeight,
        state.hStackGap,
        state.vStackGap,
        state.hBeamW,
        state.hBeamT,
        state.vBeamW,
        state.vBeamT,
        state.vBeamDimensionsLinked,
        state.vBeamInnerW,
        state.vBeamInnerT,
        state.vBeamOuterW,
        state.vBeamOuterT,
        state.showBrackets,
        state.showBolts,
        state.showHardwareFullDetail,
        state.orientation,
        state.structureRotation,
        sp.enabled,
        sp.layoutMode,
        sp.presetId
    ];
    return params.join('|');
}

function getMeshSceneCounts(data) {
    const hwCount = (state.showHardwareFullDetail && data.hardwareAssemblyPlacements)
        ? data.hardwareAssemblyPlacements.filter(p => p.assemblyId === 'outerVBeam').length
        : 0;
    const washerCount = (state.showBolts && data.washers)
        ? data.washers.filter(w => (w.thickness || 0) > 0).length
        : 0;
    return {
        beams: data.beams ? data.beams.length : 0,
        panels: data.panels ? data.panels.length : 0,
        brackets: (state.showBrackets && data.brackets) ? data.brackets.length : 0,
        bolts: (state.showBolts && data.bolts) ? data.bolts.length : 0,
        washers: washerCount,
        hardware: hwCount
    };
}

function meshSceneCountsMatch(data, counts) {
    if (!counts) return false;
    const c = getMeshSceneCounts(data);
    return c.beams === counts.beams &&
        c.panels === counts.panels &&
        c.brackets === counts.brackets &&
        c.bolts === counts.bolts &&
        c.washers === counts.washers &&
        c.hardware === counts.hardware;
}

function disposeSceneObject(obj) {
    if (!obj) return;
    if (obj.children && obj.children.length > 0) {
        [...obj.children].forEach(child => disposeSceneObject(child));
    }
    if (obj.geometry && !obj.geometry._cacheKey) obj.geometry.dispose();
    if (obj.material) {
        if (Array.isArray(obj.material)) {
            obj.material.forEach(m => { if (!m._cacheKey) m.dispose(); });
        } else if (!obj.material._cacheKey) {
            obj.material.dispose();
        }
    }
}

function removeGroupChildAt(group, index) {
    const child = group.children[index];
    if (!child) return;
    group.remove(child);
    disposeSceneObject(child);
}

function getBeamWoodColor(beam, isColliding) {
    if (isColliding) {
        return new THREE.Color(0.9, 0.2, 0.1);
    }
    if (beam.kinematicState === 'error') {
        return new THREE.Color(0.82, 0.28, 0.18);
    }
    if (beam.kinematicState === 'warning') {
        return new THREE.Color(0.72, 0.52, 0.18);
    }
    const base = beam.colorBase;
    return new THREE.Color(
        Math.max(0, (base.r * 0.7 - 20)) / 255,
        Math.max(0, (base.g * 0.65 - 15)) / 255,
        Math.max(0, (base.b * 0.5 - 10)) / 255
    );
}

function buildBeamGeometryArrays(beam) {
    const c = beam.corners;
    const positions = [];
    const normals = [];

    function calcOutwardNormal(p0, p1, p2, faceCenter, beamCenter) {
        const ax = p1.x - p0.x, ay = p1.y - p0.y, az = p1.z - p0.z;
        const bx = p2.x - p0.x, by = p2.y - p0.y, bz = p2.z - p0.z;
        let nx = ay * bz - az * by;
        let ny = az * bx - ax * bz;
        let nz = ax * by - ay * bx;
        const len = Math.sqrt(nx * nx + ny * ny + nz * nz) || 1;
        nx /= len; ny /= len; nz /= len;
        const toCenterX = beamCenter.x - faceCenter.x;
        const toCenterY = beamCenter.y - faceCenter.y;
        const toCenterZ = beamCenter.z - faceCenter.z;
        const dot = nx * toCenterX + ny * toCenterY + nz * toCenterZ;
        if (dot > 0) { nx = -nx; ny = -ny; nz = -nz; }
        return { x: nx, y: ny, z: nz };
    }

    let cx = 0, cy = 0, cz = 0;
    for (let i = 0; i < 8; i++) { cx += c[i].x; cy += c[i].y; cz += c[i].z; }
    const beamCenter = { x: cx / 8, y: cy / 8, z: cz / 8 };

    function addQuad(p0, p1, p2, p3) {
        const faceCenter = {
            x: (p0.x + p1.x + p2.x + p3.x) / 4,
            y: (p0.y + p1.y + p2.y + p3.y) / 4,
            z: (p0.z + p1.z + p2.z + p3.z) / 4
        };
        const n = calcOutwardNormal(p0, p1, p2, faceCenter, beamCenter);
        positions.push(p0.x, p0.y, p0.z, p1.x, p1.y, p1.z, p2.x, p2.y, p2.z);
        normals.push(n.x, n.y, n.z, n.x, n.y, n.z, n.x, n.y, n.z);
        positions.push(p0.x, p0.y, p0.z, p2.x, p2.y, p2.z, p3.x, p3.y, p3.z);
        normals.push(n.x, n.y, n.z, n.x, n.y, n.z, n.x, n.y, n.z);
    }

    addQuad(c[0], c[1], c[2], c[3]);
    addQuad(c[4], c[7], c[6], c[5]);
    addQuad(c[0], c[4], c[5], c[1]);
    addQuad(c[2], c[6], c[7], c[3]);
    addQuad(c[0], c[3], c[7], c[4]);
    addQuad(c[1], c[5], c[6], c[2]);

    return { positions, normals };
}

function updateSolidBeamMesh(mesh, beam, isColliding, sc) {
    const { positions, normals } = buildBeamGeometryArrays(beam);
    const posAttr = mesh.geometry.attributes.position;
    const normAttr = mesh.geometry.attributes.normal;
    if (posAttr.count * 3 !== positions.length) return false;
    posAttr.array.set(new Float32Array(positions));
    normAttr.array.set(new Float32Array(normals));
    posAttr.needsUpdate = true;
    normAttr.needsUpdate = true;
    mesh.geometry.computeBoundingSphere();
    mesh.material.color.copy(getBeamWoodColor(beam, isColliding));
    mesh.userData.beam = beam;
    mesh.position.set(-sc.x, -sc.y, -sc.z);
    mesh.castShadow = state.shadowsEnabled || false;
    mesh.receiveShadow = state.shadowsEnabled || false;
    return true;
}

function offsetSceneMesh(mesh, sc) {
    mesh.position.x -= sc.x;
    mesh.position.y -= sc.y;
    mesh.position.z -= sc.z;
    return mesh;
}

function syncMeshGroup(group, count, createAtIndex, updateAtIndex) {
    while (group.children.length > count) {
        removeGroupChildAt(group, group.children.length - 1);
    }
    for (let i = 0; i < count; i++) {
        let mesh = group.children[i];
        if (mesh && updateAtIndex(mesh, i)) continue;
        if (mesh) removeGroupChildAt(group, i);
        mesh = createAtIndex(i);
        if (i < group.children.length) {
            group.children[i] = mesh;
            mesh.parent = group;
        } else {
            group.add(mesh);
        }
    }
}

function canReuseThreeJSSceneMeshes(data) {
    const key = computeMeshStructureKey();
    return threeRendererMeshStructureKey === key && meshSceneCountsMatch(data, threeRendererMeshCounts);
}

