    if (state.showBolts && data.bolts) {
        syncMeshGroup(threeRenderer.boltGroup, data.bolts.length,
            (i) => offsetSceneMesh(createBoltMesh(data.bolts[i]), sc),
            (mesh, i) => {
                const bolt = data.bolts[i];
                mesh.position.set(bolt.center.x - sc.x, bolt.center.y - sc.y, bolt.center.z - sc.z);
